  string Safe(string v){return (v??"").ToLowerInvariant();}
  string[] ExtractTags(string text){return (text??"").Split(new[]{' ','\r','\n','\t',',','.'},StringSplitOptions.RemoveEmptyEntries).Where(x=>x.StartsWith("#")||x.StartsWith("@")).Distinct(StringComparer.OrdinalIgnoreCase).Take(8).ToArray();}
  void NotifyMentions(string text){foreach(var token in ExtractTags(text).Where(x=>x.StartsWith("@"))){var name=token.TrimStart('@').TrimEnd(':',';','!','?');var u=db.Data.Users.FirstOrDefault(x=>string.Equals(x.Username,name,StringComparison.OrdinalIgnoreCase));if(u!=null&&u.Id!=Session.CurrentUser.Id)Notify(u.Id,"@"+Session.CurrentUser.Username+" mentioned you in a post.");}}
