);if(u.Id!=Session.CurrentUser.Id){var msg=Btn("Message",content.ClientSize.Width-175,445,120);msg.Anchor=AnchorStyles.Top|AnchorStyles.Right;msg.Click+=(ss,ee)=>ShowMessages();content.Controls.Add(msg);}content.Controls.Add(Txt(string.IsNullOrWhiteSpace(u.Bio)?"No bio yet.":u.Bio,62,424,700,42));var stats=new ModernPanel{Location=new Point(62,480),Size=new Size(Math.Max(560,content.ClientSize.Width-165),96),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,BackColor=ThemeColors.Surface,BorderRadius=24,BorderColor=ThemeColors.BorderColor,BorderSize=1};stats.Controls.Add(new Label{Text=mine.Count+"\nPosts",Location=new Point(30,20),Size=new Size(100,55),TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",10,FontStyle.Bold)});stats.Controls.Add(new Label{Text=followers+"\nFollowers",Location=new Point(155,20),Size=new Size(110,55),TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",10,FontStyle.Bold)});stats.Controls.Add(new Label{Text=u.FollowingIds.Count+"\nFollowing",Location=new Point(290,20),Size=new Size(110,55),TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",10,FontStyle.Bold)});content.Controls.Add(stats);int actionY=595;if(u.Id==Session.CurrentUser.Id){var edit=Btn("Edit profile",62,actionY,130);edit.Click+=(ss,ee)=>ShowEditProfile();content.Controls.Add(edit);}else{var follow=Btn(Session.CurrentUser.FollowingIds.Contains(u.Id)?"Following":"+ Follow",62,actionY,120);follow.Click+=(ss,ee)=>{if(Session.CurrentUser.FollowingIds.Contains(u.Id))Session.CurrentUser.FollowingIds.Remove(u.Id);else Session.CurrentUser.FollowingIds.Add(u.Id);db.Save();ShowUserProfile(u);};content.Controls.Add(follow);var message=Btn("Message",195,actionY,110);message.Click+=(ss,ee)=>ShowMessages();content.Controls.Add(message);var block=Btn(Session.CurrentUser.BlockedUserIds.Contains(u.Id)?"Unblock":"Block",318,actionY,100);block.BackColor=ThemeColors.SurfaceHover;block.ForeColor=ThemeColors.AlertRed;block.Click+=(ss,ee)=>{if(Session.CurrentUser.BlockedUserIds.Contains(u.Id))Session.CurrentUser.BlockedUserIds.Remove(u.Id);else Session.CurrentUser.BlockedUserIds.Add(u.Id);db.Save();ShowUserProfile(u);};content.Controls.Add(block);}content.Controls.Add(Section("Posts",62,660));int y=700;if(mine.Count==0){content.Controls.Add(EmptyState("✦","No posts yet","Published posts will appear on this profile.",y));return;}foreach(var p in mine){var c=PostCard(p,y);content.Controls.Add(c);y+=c.Height+16;}}
