  void ShowEditProfile(){Page("Edit Profile");var u=Session.CurrentUser;content.Controls.Add(Txt("Bio",35,85));var bio=new TextBox{Text=u.Bio??"",Location=new Point(35,115),Size=new Size(600,80),Multiline=true,MaxLength=220};content.Controls.Add(bio);content.Controls.Add(Txt("Location",35,215));var loc=new TextBox{Text=u.Location??"",Location=new Point(35,245),Width=400};content.Controls.Add(loc);var avatar=Btn("Choose Avatar",455,240,150);avatar.Click+=(s,e)=>{using(var d=new OpenFileDialog{Filter="Images|*.jpg;*.jpeg;*.png;*.bmp"})if(d.ShowDialog(this)==DialogResult.OK){u.AvatarPath=d.FileName;db.Save();}};content.Controls.Add(avatar);var save=Btn("Save Profile",35,305,160);save.Click+=(s,e)=>{u.Bio=bio.Text.Trim();u.Location=loc.Text.Trim();db.Save();ShowProfile();};content.Controls.Add(save);}

  void ToggleFocusMode(){aside.Visible=!aside.Visible;toast.ShowMessage(this,aside.Visible?"Focus mode off":"Focus mode on");}
  void ShowCommandPalette(){using(var f=new Form{Text="Command Palette",StartPosition=FormStartPosition.CenterParent,Size=new Size(520,570),BackColor=ThemeColors.Background,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){f.Controls.Add(new Label{Text="Quick actions",Location=new Point(24,20),AutoSize=true,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",16,FontStyle.Bold)});var search=new TextBox{Location=new Point(24,62),Size=new Size(455,34),Font=new Font("Segoe UI",11),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};f.Controls.Add(search);var list=new ListBox{Location=new Point(24,112),Size=new Size(455,370),Font=new Font("Segoe UI",10),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};string[] names={"Feed","Explore","Messages","Notifications","Friends","Communities","Events","Polls","Saved Posts","Collections","Creator Studio","Content Planner","Insights","Profile","Safety Center","Activity","Security","Admin Center","Engineering Overview","Diagnostics","Settings","What's New","Project Showcase","Toggle Focus Mode"};Action[] acts={ShowFeed,ShowExplore,ShowMessages,ShowNotifications,ShowFriends,ShowCommunities,ShowEvents,ShowPolls,ShowSavedPosts,ShowCollections,ShowCreatorStudio,ShowPlanner,ShowInsights,ShowProfile,ShowSafetyCenter,ShowActivity,ShowSecurityCenter,ShowAdminCenter,ShowEngineeringOverview,ShowDiagnosticsCenter,ShowSettings,ShowWhatsNew,ShowProjectShowcase,ToggleFocusMode};var filtered=names.ToList();Action refresh=()=>{var q=(search.Text??"").Trim().ToLowerInvariant();filtered=names.Where(x=>x.ToLowerInvariant().Contains(q)).ToList();list.Items.Clear();foreach(var n in filtered)list.Items.Add(n);};Action open=()=>{if(list.SelectedIndex<0)return;var n=filtered[list.SelectedIndex];var idx=Array.IndexOf(names,n);f.Close();acts[idx]();};search.TextChanged+=(a,b)=>refresh();search.KeyDown+=(a,b)=>{if(b.KeyCode==Keys.Down&&list.Items.Count>0){list.SelectedIndex=0;list.Focus();b.SuppressKeyPress=true;}else if(b.KeyCode==Keys.Enter&&list.Items.Count>0){list.SelectedIndex=0;open();b.SuppressKeyPress=true;}};list.DoubleClick+=(a,b)=>open();list.KeyDown+=(a,b)=>{if(b.KeyCode==Keys.Enter){open();b.SuppressKeyPress=true;}};refresh();f.Shown+=(a,b)=>search.Focus();f.ShowDialog(this);}}
  void ShowProjectShowcase(){Page("Project Showcase");content.Controls.Add(PageBanner("PORTFOLIO","Engineering Showcase","A recruiter-friendly overview of the product architecture, UX systems and desktop engineering capabilities.",260));string[] cards={"DESKTOP UX|Premium WinForms design system, responsive panels, keyboard navigation and focus mode.","SOCIAL CORE|Feed, profiles, friendships, stories, notifications, saved posts and media discovery.","MESSAGING|Direct and group messaging, replies, reactions, forwarding, attachments, drafts, archive and presence.","COMMUNITIES|Communities, events, polls, collections and member-oriented workflows.","CREATOR TOOLS|Creator Studio, drafts, scheduling, insights and content planning.","TRUST & ADMIN|Privacy controls, reports, moderation, roles, sessions, recovery and audit-oriented workflows.","ENGINEERING|Service layer, backup, diagnostics, reusable controls, validation and global error handling."};int y=398;foreach(var item in cards){var a=item.Split('|');var c=new AccentCard{Location=new Point(35,y),Size=new Size(Math.Max(620,content.ClientSize.Width-110),86),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};c.Controls.Add(new Label{Text=a[0],Location=new Point(18,15),AutoSize=true,ForeColor=ThemeColors.Primary,Font=new Font("Segoe UI Semibold",8.5F,FontStyle.Bold)});c.Controls.Add(new Label{Text=a[1],Location=new Point(18,40),Size=new Size(c.Width-40,32),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI",9)});content.Controls.Add(c);y+=98;}}
  void ShowWhatsNew(){Page("What's New");content.Controls.Add(PageBanner("Release","Ashkan Social · Stage 45","A polished desktop social experience with productivity, messaging and community tools.",250));var items=new[]{"⌘  Command Palette|Jump anywhere with Ctrl+P and live filtering.","💬  Messenger Workspace|Drafts, replies, reactions, forwarding, archives, attachments and group chats.","🌐  Community Tools|Communities, events, polls and collections in one workspace.","✨  Creator Suite|Drafts, scheduling, insights and creator-oriented publishing tools.","🛡  Trust & Security|Privacy, blocking, reports, sessions, recovery and moderation workflows.","⌨  Desktop Shortcuts|Ctrl+K Explore · Ctrl+M Messages · Ctrl+N Creator Studio · F5 Feed."};int y=398;foreach(var item in items){var parts=item.Split('|');var card=new AccentCard{Location=new Point(35,y),Size=new Size(Math.Max(620,content.ClientSize.Width-110),82),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};card.Controls.Add(new Label{Text=parts[0],Location=new Point(18,15),AutoSize=true,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",10.5F,FontStyle.Bold)});card.Controls.Add(new Label{Text=parts[1],Location=new Point(18,43),Size=new Size(card.Width-40,24),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,ForeColor=ThemeColors.TextMuted,Font=new Font("Segoe UI",8.8F)});content.Controls.Add(card);y+=94;}}
  void MainShortcuts(object sender,KeyEventArgs e){if(e.Control&&e.Shift&&e.KeyCode==Keys.F){ToggleFocusMode();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.P){ShowCommandPalette();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.K){ShowExplore();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.N){ShowCreatorStudio();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.M){ShowMessages();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.F5){ShowFeed();e.SuppressKeyPress=true;}}
  public void ShowSavedPosts(){Page("Saved");var posts=db.Data.Posts.Where(x=>x.SavedBy.Contains(Session.CurrentUser.Id)).OrderByDescending(x=>x.CreatedAt).ToList();content.Controls.Add(PageBanner("Library","Saved posts","Keep useful conversations, ideas and media close at hand.",158));content.Controls.Add(StatCard("Saved items",posts.Count.ToString(),35,292,190));content.Controls.Add(StatCard("With media",posts.Count(x=>!string.IsNullOrWhiteSpace(x.ImagePath)).ToString(),240,292,190));int y=420;if(posts.Count==0){content.Controls.Add(EmptyState("☆","Nothing saved yet","Use Save on a post and it will appear in your personal library.",y));return;}foreach(var p in posts){var c=PostCard(p,y);content.Controls.Add(c);y+=c.Height+16;}}
  void BuildStories(){db.Data.Stories.RemoveAll(x=>x.CreatedAt<DateTime.Now.AddHours(-24));var wrap=new ModernPanel{Location=new Point(35,340),Size=new Size(Math.Max(650,content.ClientSize.Width-100),150),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,BackColor=Color.FromArgb(18,38,64),BorderRadius=22,BorderColor=Color.FromArgb(55,83,118),BorderSize=1};wrap.Controls.Add(new Label{Text="Stories",Location=new Point(16,10),AutoSize=true,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",11,FontStyle.Bold)});var strip=new FlowLayoutPanel{Location=new Point(14,38),Size=new Size(wrap.Width-28,102),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,AutoScroll=true,WrapContents=false,FlowDirection=FlowDirection.LeftToRight,BackColor=Color.FromArgb(18,38,64),Padding=new Padding(2)};var addCard=new ModernPanel{Size=new Size(82,88),BackColor=Color.FromArgb(28,51,82),BorderRadius=24,BorderColor=ThemeColors.Primary,BorderSize=2,Margin=new Padding(0,2,10,2)};var plus=new Label{Text="+\r\nCreate",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",9),Cursor=Cursors.Hand};plus.Click+=(ss,ee)=>AddStory();addCard.Controls.Add(plus);strip.Controls.Add(addCard);foreach(var st in db.Data.Stories.OrderByDescending(x=>x.CreatedAt)){var u=db.Data.Users.FirstOrDefault(x=>x.Id==st.UserId);var card=new ModernPanel{Size=new Size(82,88),BackColor=Color.FromArgb(28,51,82),BorderRadius=24,BorderColor=ThemeColors.Primary,BorderSize=2,Margin=new Padding(0,2,10,2),Cursor=Cursors.Hand};var name=u==null?"Story":u.FullName.Split(' ')[0];var initials=new Label{Text=(u==null?"S":string.Join("",u.FullName.Split(' ').Where(q=>q.Length>0).Take(2).Select(q=>q.Substring(0,1))).ToUpperInvariant())+"\r\n"+name,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",8.5F)};initials.Click+=(ss,ee)=>ViewStory(st);card.Controls.Add(initials);strip.Controls.Add(card);}wrap.Controls.Add(strip);content.Controls.Add(wrap);}
  void AddStory(){string text=Prompt("Story text (optional)","Create Story");string path=null;using(var d=new OpenFileDialog{Filter="Images|*.jpg;*.jpeg;*.png;*.bmp"}){if(d.ShowDialog(this)==DialogResult.OK)path=d.FileName;}if(string.IsNullOrWhiteSpace(text)&&string.IsNullOrWhiteSpace(path))return;db.Data.Stories.Add(new Story{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Text=text??"",ImagePath=path,CreatedAt=DateTime.Now});db.Save();ShowFeed();}
  void ViewStory(Story st){var u=db.Data.Users.FirstOrDefault(x=>x.Id==st.UserId);using(var f=new Form{Text=(u==null?"Story":u.FullName+" · Story"),StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(520,620),BackColor=ThemeColors.Background}){if(!string.IsNullOrWhiteSpace(st.ImagePath)&&File.Exists(st.ImagePath)){try{var pic=new PictureBox{Location=new Point(20,20),Size=new Size(480,480),SizeMode=PictureBoxSizeMode.Zoom,BackColor=ThemeColors.Surface};using(var im=Image.FromFile(st.ImagePath))pic.Image=new Bitmap(im);f.Controls.Add(pic);}catch{}}var l=new Label{Text=st.Text??"",Location=new Point(20,515),Size=new Size(480,70),ForeColor=ThemeColors.TextPrimary,TextAlign=ContentAlignment.MiddleCenter};f.Controls.Add(l);f.ShowDialog(this);}}
  void ShowReactionMenu(Post p){using(var f=new Form{Text="React to post",StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(440,110),BackColor=ThemeColors.Background}){string[] types={"Like","Celebrate","Support","Insightful"};for(int i=0;i<types.Length;i++){var type=types[i];var b=Btn(type,15+i*105,30,95);b.Click+=(s,e)=>{p.Reactions.RemoveAll(x=>x.UserId==Session.CurrentUser.Id);p.Reactions.Add(new PostReaction{UserId=Session.CurrentUser.Id,Type=type});LogActivity("Reacted "+type.ToLowerInvariant()+" to a post");db.Save();f.Close();ShowFeed();};f.Controls.Add(b);}f.ShowDialog(this);}}
  void ReportUser(User u){string reason=Prompt("Reason for report","Report @"+u.Username);if(string.IsNullOrWhiteSpace(reason))return;db.Data.Reports.Add(new ReportItem{Id=Guid.NewGuid().ToString(),ReporterUserId=Session.CurrentUser.Id,TargetUserId=u.Id,Reason=reason.Trim(),CreatedAt=DateTime.Now,Status="Open"});LogActivity("Reported @"+u.Username);db.Save();MessageBox.Show("Thanks. Your report was recorded locally for review.","Report submitted");}
  void LogActivity(string action){db.Data.Activities.Add(new ActivityItem{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Action=action,CreatedAt=DateTime.Now});}
  public void ShowActivity(){Page("Activity");var items=db.Data.Activities.Where(x=>x.UserId==Session.CurrentUser.Id).OrderByDescending(x=>x.CreatedAt).Take(100).ToList();content.Controls.Add(PageBanner("History","Activity log","A private timeline of important actions performed from your account.",158));content.Controls.Add(StatCard("Recent actions",items.Count.ToString(),35,292,190));int y=420;if(items.Count==0){content.Controls.Add(EmptyState("↻","No activity yet","Important actions will be listed here as you use Ashkan Social.",y));return;}foreach(var a in items){var c=Card(y,82);var icon=new ModernPanel{Location=new Point(16,17),Size=new Size(46,46),BackColor=ThemeColors.SurfaceHover,BorderRadius=18,BorderColor=ThemeColors.BorderColor,BorderSize=1};icon.Controls.Add(new Label{Text="↻",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.Primary,Font=new Font("Segoe UI",12,FontStyle.Bold)});c.Controls.Add(icon);c.Controls.Add(new Label{Text=a.Action,Location=new Point(80,15),Size=new Size(c.Width-110,28),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",9.5F)});c.Controls.Add(new Label{Text=a.CreatedAt.ToString("MMM d, yyyy · HH:mm"),Location=new Point(80,49),AutoSize=true,ForeColor=ThemeColors.TextMuted});content.Controls.Add(c);y+=94;}}
  void EnsureCurrentSession(){if(Session.CurrentUser==null)return;var active=db.Data.Sessions.FirstOrDefault(x=>x.UserId==Session.CurrentUser.Id&&!x.Revoked&&x.DeviceName==Environment.MachineName);if(active==null)db.Data.Sessions.Add(new UserSession{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,DeviceName=Environment.MachineName,CreatedAt=DateTime.Now,LastActiveAt=DateTime.Now});else active.LastActiveAt=DateTime.Now;}
  void Notify(string uid,string text){db.Data.Notifications.Add(new NotificationItem{Id=Guid.NewGuid().ToString(),UserId=uid,Text=text,CreatedAt=DateTime.Now});}
  string Prompt(string label,string caption){using(var f=new Form{Text=caption,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(430,180),BackColor=ThemeColors.Background}){var l=Txt(label,20,20,380);f.Controls.Add(l);var t=new TextBox{Location=new Point(20,55),Width=385};f.Controls.Add(t);var ok=Btn("OK",290,105,115);ok.DialogResult=DialogResult.OK;f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK?t.Text:null;}}
 
  public void ShowDiagnosticsCenter(){Page("Diagnostics");content.Controls.Add(PageBanner("Reliability","Diagnostics Center","Inspect the local runtime and export a support-friendly environment report.",205));var report=DiagnosticsService.BuildReport();var card=Card(330,300);card.Controls.Add(new Label{Text="Environment report",Location=new Point(18,16),AutoSize=true,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",12,FontStyle.Bold)});var box=new TextBox{Location=new Point(18,52),Size=new Size(card.Width-36,165),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.FromArgb(15,31,53),ForeColor=Color.FromArgb(205,222,238),BorderStyle=BorderStyle.FixedSingle,Font=new Font("Consolas",9),Text=report};card.Controls.Add(box);var save=Btn("Save report",18,235,125);save.Click+=(ss,ee)=>{using(var d=new FolderBrowserDialog()){if(d.ShowDialog(this)==DialogResult.OK){var path=DiagnosticsService.SaveReport(d.SelectedPath);toast.ShowMessage(this,"Diagnostics saved");MessageBox.Show("Saved to:\r\n"+path,"Diagnostics",MessageBoxButtons.OK,MessageBoxIcon.Information);}}};card.Controls.Add(save);var copy=Btn("Copy",155,235,95);copy.BackColor=Color.FromArgb(31,54,86);copy.Click+=(ss,ee)=>{Clipboard.SetText(report);toast.ShowMessage(this,"Diagnostics copied");};card.Controls.Add(copy);content.Controls.Add(card);var health=Card(650,145);health.Controls.Add(new Label{Text="Runtime health",Location=new Point(18,16),AutoSize=true,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",11,FontStyle.Bold)});health.Controls.Add(new Label{Text="Realtime transport: "+realtime.GetType().Name+"\r\nConnection state: "+realtime.State+"\r\nLocal persistence: available",Location=new Point(18,48),AutoSize=true,ForeColor=ThemeColors.TextSecondary,Font=new Font("Segoe UI",9.5F)});content.Controls.Add(health);}
